    lrx_c2 acc[EPT];

    // --- the element's 3-D index, decomposed ONCE for all six passes ---
    int kx[EPT], ky[EPT], kz[EPT];
#pragma unroll
    for (int e = 0; e < EPT; ++e) {
        int t = lane + e * tpr;
        if (t >= nk) t = 0;                 // inactive lane: keep it in range
        kz[e] = t % n2; t /= n2;
        ky[e] = t % n1;
        kx[e] = t / n1;
