    {                                                                         \
        const lrx_c2* wp = wgt + meta[threadIdx.y];                           \
        _Pragma("unroll")                                                     \
        for (int e = 0; e < EPT; ++e) {                                       \
            const int k = lane + e * tpr;                                     \
            if (k < nk) {                                                     \
                const lrx_c2 w = wp[k];                                       \
                const double ar = acc[e].x, ai = acc[e].y;                    \
                acc[e].x = ar * w.x - ai * w.y;                               \
                acc[e].y = ar * w.y + ai * w.x;                               \
            }                                                                 \
        }                                                                     \
    }
